B.amH=new A.aJ("Remembrance at Muzdalifah","\u0627\u0644\u0630\u0643\u0631 \u0628\u0627\u0644\u0645\u0632\u062f\u0644\u0641\u0629")
B.ame=new A.aJ("After Arafah comes the night at Muzdalifah. After Fajr, the Prophet faced the qiblah, made duaa, takbir and tahlil, and departed before sunrise. No fixed long supplication is specified. Those with a concession may leave earlier with their group.","\u0628\u0639\u062f \u0639\u0631\u0641\u0629 \u062a\u0643\u0648\u0646 \u0644\u064a\u0644\u0629 \u0627\u0644\u0645\u0632\u062f\u0644\u0641\u0629. \u0648\u0628\u0639\u062f \u0627\u0644\u0641\u062c\u0631 \u0627\u0633\u062a\u0642\u0628\u0644 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0627\u0644\u0642\u0628\u0644\u0629 \u0648\u062f\u0639\u0627 \u0648\u0643\u0628\u0651\u0631 \u0648\u0647\u0644\u0651\u0644\u060c \u062b\u0645 \u062f\u0641\u0639 \u0642\u0628\u0644 \u0637\u0644\u0648\u0639 \u0627\u0644\u0634\u0645\u0633. \u0644\u0627 \u062a\u062d\u062f\u062f \u0631\u0648\u0627\u064a\u0629 \u062c\u0627\u0628\u0631 \u062f\u0639\u0627\u0621\u064b \u0637\u0648\u064a\u0644\u0627\u064b \u062e\u0627\u0635\u064b\u0627. \u0648\u0644\u0623\u0647\u0644 \u0627\u0644\u0623\u0639\u0630\u0627\u0631 \u0631\u062e\u0635\u0629 \u0641\u064a \u0627\u0644\u062f\u0641\u0639 \u0627\u0644\u0645\u0628\u0643\u0631 \u0645\u0639 \u0645\u062c\u0645\u0648\u0639\u062a\u0647\u0645.")
B.amv=new A.aJ("Stay at Muzdalifah and remember Allah","\u0628\u062a \u0628\u0627\u0644\u0645\u0632\u062f\u0644\u0641\u0629 \u0648\u0627\u0630\u0643\u0631 \u0627\u0644\u0644\u0647")
