B.ann=new A.aJ("8 Dhul-Hijjah","\u0668 \u0630\u0648 \u0627\u0644\u062d\u062c\u0629")
B.a2n=new A.n3(2,"tents")
B.amJ=new A.aJ("Mina \u2022 Day of Tarwiyah","\u0645\u0646\u0649 \u2022 \u064a\u0648\u0645 \u0627\u0644\u062a\u0631\u0648\u064a\u0629")
B.an5=new A.aJ("On 8 Dhul-Hijjah, pilgrims go to Mina and stay until the next morning. Continue Talbiyah. No separate fixed duaa is supplied for the journey from Makkah to Mina or on the way to Arafah.","\u0641\u064a \u0627\u0644\u062b\u0627\u0645\u0646 \u0645\u0646 \u0630\u064a \u0627\u0644\u062d\u062c\u0629 \u064a\u062a\u0648\u062c\u0647 \u0627\u0644\u062d\u062c\u0627\u062c \u0625\u0644\u0649 \u0645\u0646\u0649 \u0648\u064a\u0628\u064a\u062a\u0648\u0646 \u0625\u0644\u0649 \u0635\u0628\u0627\u062d \u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u062a\u0627\u0644\u064a \u0645\u0639 \u0627\u0644\u062a\u0644\u0628\u064a\u0629. \u0644\u0627 \u0646\u0648\u0631\u062f \u062f\u0639\u0627\u0621\u064b \u062e\u0627\u0635\u064b\u0627 \u0644\u0644\u0637\u0631\u064a\u0642 \u0645\u0646 \u0645\u0643\u0629 \u0625\u0644\u0649 \u0645\u0646\u0649 \u0623\u0648 \u0625\u0644\u0649 \u0639\u0631\u0641\u0629.")
